//! GF(2^288) known-answer and law tests.
#![allow(clippy::arithmetic_side_effects)] // field operators are total; no integer overflow.
//!
//! The vectors are generated by the independent Python reference model
//! (`model/vorb3_model.py`, SP-288 profile).

use vorb3::field::F288;

const A: [u8; 36] = [
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
    0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
    0x20, 0x21, 0x22, 0x23,
];

const B: [u8; 36] = [
    0x80, 0x81, 0x82, 0x83, 0x84, 0x85, 0x86, 0x87, 0x88, 0x89, 0x8a, 0x8b, 0x8c, 0x8d, 0x8e, 0x8f,
    0x90, 0x91, 0x92, 0x93, 0x94, 0x95, 0x96, 0x97, 0x98, 0x99, 0x9a, 0x9b, 0x9c, 0x9d, 0x9e, 0x9f,
    0xa0, 0xa1, 0xa2, 0xa3,
];

const A_MUL_B: [u8; 36] = [
    0x02, 0x0a, 0x07, 0x3a, 0x32, 0xc7, 0x23, 0xce, 0x32, 0xfb, 0x13, 0xf2, 0xe2, 0x0f, 0xf0, 0x06,
    0xa1, 0x23, 0xe0, 0x2a, 0xd1, 0xd7, 0xc0, 0xde, 0xd1, 0xeb, 0xf0, 0xe2, 0x01, 0x10, 0x2f, 0x19,
    0x7e, 0x1d, 0xff, 0x14,
];

const A_INV: [u8; 36] = [
    0x99, 0x92, 0xcb, 0xac, 0xa0, 0x0a, 0xf1, 0xfd, 0xa3, 0x10, 0xd6, 0xb8, 0x91, 0x62, 0x49, 0xf3,
    0xa5, 0x39, 0x02, 0xd7, 0xd2, 0xf7, 0xf7, 0x62, 0x8b, 0xa7, 0x9a, 0x43, 0x73, 0x51, 0xbf, 0xf4,
    0x05, 0x0f, 0x6b, 0x8a,
];

const A_SQ: [u8; 36] = [
    0x5c, 0x73, 0x03, 0x3f, 0x38, 0xc3, 0x3a, 0xcf, 0x20, 0xf3, 0x22, 0xff, 0xd8, 0x03, 0xd9, 0x0f,
    0x83, 0x33, 0x81, 0x3f, 0xbb, 0xc3, 0xb9, 0xcf, 0xa3, 0xf3, 0xa1, 0xff, 0x5b, 0x0c, 0x66, 0x00,
    0x3c, 0x3d, 0x3e, 0x31,
];

const A_ADD_B: [u8; 36] = [
    0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80,
    0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80,
    0x80, 0x80, 0x80, 0x80,
];

#[test]
fn field_kat_mul_add_square_inverse() {
    let a = F288::from_bytes(A);
    let b = F288::from_bytes(B);
    assert_eq!(a * b, F288::from_bytes(A_MUL_B));
    assert_eq!(a + b, F288::from_bytes(A_ADD_B));
    assert_eq!(a.square(), F288::from_bytes(A_SQ));
    assert_eq!(a.inverse(), F288::from_bytes(A_INV));
    assert_eq!(a * a.inverse(), F288::ONE);
    assert_eq!(F288::ZERO.inverse(), F288::ZERO);
    assert_eq!(F288::ONE.inverse(), F288::ONE);
}

#[test]
fn field_laws_and_encoding() {
    let a = F288::from_bytes(A);
    let b = F288::from_bytes(B);
    let zero = F288::ZERO;
    let one = F288::ONE;

    assert_eq!(a + zero, a);
    assert_eq!(a * zero, zero);
    assert_eq!(a * one, a);
    assert_eq!(a + a, zero);
    assert_eq!(a + b, b + a);
    assert_eq!(a * b, b * a);
    assert_eq!((a + b) + a, b);
    assert_eq!(a * (b + one), a * b + a);
    assert!(zero.is_zero());
    assert!(!one.is_zero());
    assert_eq!(F288::from_u64(2) * F288::from_u64(3), F288::from_u64(6));

    assert_eq!(F288::from_bytes(a.to_bytes()), a);
    assert_eq!(F288::from_bytes(B).to_bytes(), B);
}
